def inject_styles():
    import streamlit as st
    st.markdown('''
    <style>
    @import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Inter:wght@400;500;600;700&display=swap');
    :root { --bg:#09131f; --bg2:#0d1927; --panel:rgba(18,30,46,.64); --panel-soft:rgba(24,38,56,.48); --border:rgba(180,196,216,.14); --border-strong:rgba(180,196,216,.25); --text:#eaf0f7; --muted:#8f9caf; --accent:#7fa7d8; --success:#73b69b; --warning:#d4a76a; --danger:#d67d86; --sans:'Inter',sans-serif; --mono:'DM Mono',monospace; }
    html,body,[class*="css"]{font-family:var(--sans);}
    .stApp{background:radial-gradient(circle at 18% 0%,rgba(96,130,170,.12),transparent 30%),radial-gradient(circle at 85% 12%,rgba(102,139,132,.07),transparent 27%),linear-gradient(145deg,var(--bg),var(--bg2));color:var(--text);}
    #MainMenu,footer,header{visibility:hidden}.block-container{max-width:1480px;padding-top:2.1rem;padding-bottom:3rem;}
    section[data-testid="stSidebar"]{background:rgba(8,17,28,.86);backdrop-filter:blur(22px);border-right:1px solid var(--border);}section[data-testid="stSidebar"] *{color:var(--text)}
    .resolve-kicker,.section-label,.metric-label,.loop-key{font-family:var(--mono);font-size:.68rem;letter-spacing:.11em;text-transform:uppercase;color:var(--muted)}
    .resolve-brand{font-size:1.65rem;font-weight:700;letter-spacing:-.04em;margin:.18rem 0}.resolve-title{font-size:2.25rem;line-height:1.1;font-weight:700;letter-spacing:-.05em;margin:.22rem 0 .6rem}.resolve-subtitle,.section-caption{color:var(--muted);font-size:.9rem;line-height:1.6;max-width:760px}.section-heading{margin-bottom:.8rem}
    .glass-card{background:var(--panel);border:1px solid var(--border);border-radius:18px;padding:1.15rem 1.25rem;backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);box-shadow:0 12px 40px rgba(0,0,0,.13),inset 0 1px 0 rgba(255,255,255,.025)}
    .metric-card{min-height:112px;padding:1rem 1.05rem;border-radius:16px;background:var(--panel-soft);border:1px solid var(--border);backdrop-filter:blur(18px)}.metric-value{font-size:1.55rem;font-weight:600;letter-spacing:-.03em;margin-top:.5rem}.metric-detail{font-size:.75rem;color:var(--muted);margin-top:.4rem}
    .status-pill{display:inline-flex;align-items:center;font-family:var(--mono);font-size:.68rem;letter-spacing:.05em;padding:.42rem .72rem;border-radius:999px;border:1px solid var(--border)}.status-success{color:var(--success);background:rgba(115,182,155,.09);border-color:rgba(115,182,155,.25)}.status-pending{color:var(--warning);background:rgba(212,167,106,.09);border-color:rgba(212,167,106,.25)}.status-danger{color:var(--danger);background:rgba(214,125,134,.09);border-color:rgba(214,125,134,.25)}.status-neutral{color:var(--accent);background:rgba(127,167,216,.09)}
    .stTextInput input,.stTextArea textarea,.stNumberInput input,.stDateInput input,.stTimeInput input,.stSelectbox div[data-baseweb="select"]>div{background:rgba(5,13,23,.38)!important;border:1px solid var(--border)!important;color:var(--text)!important;border-radius:10px!important}.stTextInput input:focus,.stTextArea textarea:focus{border-color:rgba(127,167,216,.7)!important;box-shadow:0 0 0 1px rgba(127,167,216,.16)!important}
    .stButton>button,.stFormSubmitButton>button{width:100%;border-radius:10px;border:1px solid rgba(127,167,216,.35);background:rgba(78,111,151,.8);color:#f4f7fb;font-weight:600;padding:.58rem 1rem}.stButton>button:hover,.stFormSubmitButton>button:hover{border-color:rgba(180,205,235,.55);background:rgba(90,125,168,.92)}
    .stTabs [data-baseweb="tab-list"]{gap:1.5rem;border-bottom:1px solid var(--border)}.stTabs [data-baseweb="tab"]{background:transparent;color:var(--muted);padding-left:0;padding-right:0}.stTabs [aria-selected="true"]{color:var(--text)}
    .pipeline{margin-top:1rem}.pipeline-step{display:flex;gap:.9rem;padding:.8rem 0;border-bottom:1px solid rgba(180,196,216,.07)}.pipeline-dot{width:9px;height:9px;border-radius:50%;margin-top:.4rem;background:#536172}.pipeline-step.complete .pipeline-dot{background:var(--success)}.pipeline-step.active .pipeline-dot{background:var(--warning);box-shadow:0 0 0 4px rgba(212,167,106,.09)}.pipeline-name{font-size:.9rem;font-weight:600}.pipeline-description{font-size:.78rem;color:var(--muted);margin-top:.18rem}.loop-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;padding:.9rem 0;border-bottom:1px solid var(--border)}.loop-summary strong{display:block;margin-top:.4rem;font-size:.9rem;text-transform:capitalize}.timeline-item{display:flex;gap:1rem;padding:1rem;border:1px solid var(--border);border-radius:14px;background:rgba(18,30,46,.45);margin-bottom:.55rem}.timeline-index{font-family:var(--mono);font-size:.72rem;color:var(--accent);padding-top:.1rem}.timeline-content{font-size:.88rem;line-height:1.55}.empty-state{padding:1rem;border:1px dashed var(--border);border-radius:12px;color:var(--muted);font-size:.85rem}
    .form-note{font-size:.76rem;color:var(--muted);margin:.3rem 0 1rem}.approval-card{border:1px solid rgba(212,167,106,.25);background:rgba(212,167,106,.055);border-radius:16px;padding:1rem 1.1rem;margin:1rem 0}.approval-title{font-weight:600;margin-bottom:.35rem}.muted{color:var(--muted)}
    [data-testid="stDataFrame"]{border:1px solid var(--border);border-radius:14px;overflow:hidden}.stAlert{border-radius:12px}
    @media(max-width:900px){.resolve-title{font-size:1.75rem}.loop-summary{grid-template-columns:1fr}.block-container{padding-left:1rem;padding-right:1rem}}
    </style>
    ''', unsafe_allow_html=True)
